) VALUES (
    'livigno-venue-guide',
    '{"en": "Livigno: High-Altitude Winter Paradise", "de": "Livigno: Hochgelegenes Winterparadies", "fr": "Livigno : Paradis hivernal en altitude", "it": "Livigno: Paradiso invernale d''alta quota", "es": "Livigno: Paraíso invernal de alta montaña", "pt": "Livigno: Paraíso de inverno em alta altitude", "nl": "Livigno: Hooggelegen winterparadijs", "ar": "ليفينيو: جنة شتوية عالية الارتفاع", "ja": "リヴィーニョ：高地の冬の楽園", "zh": "Livigno: Gao Haiba Dongji Tiantang", "ko": "리비뇨: 고지대 겨울 천국"}'::jsonb,
    '{"en": "This duty-free Alpine resort at 1,800 meters offers exceptional conditions for cross-country skiing and freestyle events. A training destination for elite athletes worldwide.", "de": "Dieser zollfreie Alpenort auf 1.800 Metern bietet außergewöhnliche Bedingungen für Langlauf und Freestyle-Events.", "fr": "Cette station alpine hors taxes à 1 800 mètres offre des conditions exceptionnelles pour le ski de fond et les épreuves de freestyle.", "it": "Questa località alpina duty-free a 1.800 metri offre condizioni eccezionali per lo sci di fondo e gli eventi freestyle.", "es": "Este resort alpino libre de impuestos a 1.800 metros ofrece condiciones excepcionales para esquí de fondo y eventos freestyle.", "pt": "Este resort alpino duty-free a 1.800 metros oferece condições excepcionais para esqui cross-country e eventos freestyle.", "nl": "Dit belastingvrije Alpenresort op 1.800 meter biedt uitzonderlijke omstandigheden voor langlaufen en freestyle evenementen.", "ar": "يوفر هذا المنتجع الجبلي المعفي من الرسوم الجمركية على ارتفاع 1800 متر ظروفاً استثنائية للتزلج الريفي وفعاليات الفري ستايل", "ja": "1,800メートルにあるこの免税アルパインリゾートは、クロスカントリースキーとフリースタイルイベントに最適な条件を提供しています。", "zh": "Zhe ge weiyue 1800 mi de mianshui Aerbisi dujiacun tigong chuse de yueye huaxue he ziyoushi huaxue tiaojian.", "ko": "해발 1,800미터에 위치한 이 면세 알프스 리조트는 크로스컨트리 스키와 프리스타일 이벤트에 탁월한 조건을 제공합니다."}'::jsonb,
    '{"en": "<p>Livigno has established itself as one of Europe''s premier high-altitude winter sports destinations. This Italian resort near the Swiss border offers reliable snow conditions and world-class facilities for multiple disciplines.</p><h2>Location and Altitude</h2><p>Situated at 1,816 meters in the Lombardy region, Livigno enjoys a unique microclimate that produces excellent snow conditions throughout the winter season. The long, flat valley is ideal for <a href=\"/cross-country-skiing-guide/\">cross-country skiing</a>, while surrounding terrain provides opportunities for alpine and freestyle activities.</p><p>The resort''s duty-free status makes it a popular destination for both athletes and tourists.</p><h2>Cross-Country Facilities</h2><p>Livigno offers an extensive network of groomed cross-country trails suitable for all ability levels. The altitude and consistent snow conditions make it a favorite training destination for elite athletes preparing for competition season.</p><p>Athletes like <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> and <a href=\"/frida-karlsson-profile/\">Frida Karlsson</a> have trained in environments like Livigno to prepare for World Cup racing.</p><h2>Freestyle Venue</h2><p>The resort has developed excellent freestyle skiing facilities including halfpipe, slopestyle, and moguls courses. The Carosello 3000 area provides terrain suited for modern freestyle disciplines.</p><h2>Training Destination</h2><p>National teams from around the world use Livigno for altitude training camps. The combination of elevation, reliable conditions, and modern facilities makes it invaluable for pre-season preparation.</p><h2>Getting There</h2><p>Livigno is accessible from Milan Malpensa Airport (about 3 hours) or Innsbruck Airport. The Munt La Schera tunnel provides year-round access from Switzerland.</p><h2>Beyond Sport</h2><p>The town offers excellent dining, shopping (duty-free), and accommodation options. The vibrant après-ski scene and Italian hospitality create a complete mountain experience.</p>", "de": "<p>Livigno hat sich als eines der führenden Hochlagen-Wintersportziele Europas etabliert. Dieses italienische Resort nahe der Schweizer Grenze bietet zuverlässige Schneebedingungen und erstklassige Einrichtungen.</p><h2>Lage und Höhe</h2><p>Auf 1.816 Metern in der Lombardei gelegen, genießt Livigno ein einzigartiges Mikroklima.</p><h2>Langlauf-Einrichtungen</h2><p>Livigno bietet ein ausgedehntes Netz gespurter Langlaufloipen. Athleten wie <a href=\"/jessie-diggins-profile/\">Jessie Diggins</a> trainieren in solchen Umgebungen.</p><h2>Freestyle-Anlage</h2><p>Das Resort hat ausgezeichnete Freestyle-Ski-Anlagen entwickelt.</p>", "fr": "<p>Livigno s''est imposé comme l''une des premières destinations de sports d''hiver en altitude d''Europe. Cette station italienne près de la frontière suisse offre des conditions d''enneigement fiables.</p><h2>Emplacement et altitude</h2><p>Situé à 1 816 mètres en Lombardie, Livigno bénéficie d''un microclimat unique.</p><h2>Installations de ski de fond</h2><p>Livigno offre un vaste réseau de pistes de ski de fond.</p><h2>Site de freestyle</h2><p>La station a développé d''excellentes installations de ski freestyle.</p>", "it": "<p>Livigno si è affermato come una delle principali destinazioni europee per gli sport invernali in alta quota. Questa località italiana vicino al confine svizzero offre condizioni di neve affidabili.</p><h2>Posizione e altitudine</h2><p>Situata a 1.816 metri in Lombardia, Livigno gode di un microclima unico.</p><h2>Strutture per lo sci di fondo</h2><p>Livigno offre un''ampia rete di piste da sci di fondo.</p><h2>Sede freestyle</h2><p>La località ha sviluppato eccellenti strutture per lo sci freestyle.</p>", "es": "<p>Livigno se ha establecido como uno de los principales destinos de deportes de invierno de alta montaña de Europa. Este resort italiano cerca de la frontera suiza ofrece condiciones de nieve confiables.</p><h2>Ubicación y altitud</h2><p>Situado a 1.816 metros en Lombardía, Livigno disfruta de un microclima único.</p>", "pt": "<p>Livigno estabeleceu-se como um dos principais destinos de esportes de inverno em alta altitude da Europa. Este resort italiano perto da fronteira suíça oferece condições de neve confiáveis.</p><h2>Localização e altitude</h2><p>Situado a 1.816 metros na Lombardia, Livigno desfruta de um microclima único.</p>", "nl": "<p>Livigno heeft zich gevestigd als een van Europa''s belangrijkste hooggelegen wintersportbestemmingen. Dit Italiaanse resort nabij de Zwitserse grens biedt betrouwbare sneeuwcondities.</p><h2>Locatie en hoogte</h2><p>Gelegen op 1.816 meter in Lombardije, geniet Livigno van een uniek microklimaat.</p>", "ar": "<p>أثبتت ليفينيو نفسها كواحدة من أبرز وجهات الرياضات الشتوية المرتفعة في أوروبا. يوفر هذا المنتجع الإيطالي قرب الحدود السويسرية ظروف ثلجية موثوقة.</p><h2>الموقع والارتفاع</h2><p>تقع على ارتفاع 1816 متراً في لومبارديا.</p>", "ja": "<p>リヴィーニョは、ヨーロッパを代表する高地冬季スポーツの目的地として確立されています。スイス国境近くにあるこのイタリアのリゾートは、信頼できる雪の条件を提供しています。</p><h2>立地と標高</h2><p>ロンバルディア州の標高1,816メートルに位置するリヴィーニョは、独特のミクロ気候を楽しんでいます。</p>", "zh": "<p>Livigno yi chengwei Ouzhou zuizhongyao de gaohaiba dongji yundong mudi zhiyi. Zhe ge weiyue Ruishi bianjing fujin de Yidali dujiacun tigong kekao de xue tiaojian.</p><h2>Weizhi he haiba</h2><p>Weiyue Lunbadi haiba 1816 mi, Livigno xiangyou dute de weixiao qihou.</p>", "ko": "<p>리비뇨는 유럽 최고의 고지대 동계 스포츠 목적지 중 하나로 자리잡았습니다. 스위스 국경 근처에 위치한 이 이탈리아 리조트는 안정적인 눈 조건을 제공합니다.</p><h2>위치와 고도</h2><p>롬바르디아주 해발 1,816미터에 위치한 리비뇨는 독특한 미기후를 누리고 있습니다.</p>"}'::jsonb,
    'venue-guide',
    'XC',
    '{"en": "Livigno venue guide - High-altitude Italian resort at 1,800m offering world-class cross-country and freestyle skiing facilities in a duty-free Alpine setting.", "de": "Livigno Venue Guide - Hochgelegener italienischer Ferienort auf 1.800m mit erstklassigen Langlauf- und Freestyle-Anlagen.", "fr": "Guide du site de Livigno - Station italienne en altitude à 1 800m offrant des installations de ski de fond et freestyle de classe mondiale.", "it": "Guida alla sede di Livigno - Località italiana in alta quota a 1.800m con strutture di sci di fondo e freestyle di classe mondiale.", "es": "Guía del lugar de Livigno - Resort italiano de alta montaña a 1.800m con instalaciones de esquí de fondo y freestyle de clase mundial.", "pt": "Guia do local de Livigno - Resort italiano de alta altitude a 1.800m com instalações de esqui cross-country e freestyle de classe mundial.", "nl": "Livigno locatiegids - Hooggelegen Italiaans resort op 1.800m met wereldklasse langlauf en freestyle faciliteiten.", "ar": "دليل موقع ليفينيو - منتجع إيطالي مرتفع على ارتفاع 1800 متر مع مرافق تزلج ريفي وفري ستايل عالمية المستوى", "ja": "リヴィーニョ会場ガイド - 標高1,800mのイタリア高地リゾートで世界クラスのクロスカントリーとフリースタイルスキー施設を提供", "zh": "Livigno changguan zhinan - Haiba 1800 mi de Yidali gaohaiba dujiacun tigong shijie ji yueye huaxue he ziyoushi huaxue sheshi", "ko": "리비뇨 경기장 가이드 - 해발 1,800m의 이탈리아 고지대 리조트로 세계적 수준의 크로스컨트리 및 프리스타일 스키 시설 제공"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
